SELECT
*
FROM
mp_devops_load


        and pk = #{param.pk}


        and tool_name like concat('%', #{param.toolName}, '%')


        and action_type = #{param.actionType}


        and run_table = #{param.runTable}


        and source = #{param.source}


        and control_type = #{param.controlType}



    limit #{param.offset}, #{param.pageSize}

SELECT
*
FROM
mp_devops_load_scene_result_log


        and pk = #{param.pk}


        and tool_name like concat('%', #{param.toolName}, '%')


        and action_type = #{param.actionType}


        and run_table = #{param.runTable}


        and source = #{param.source}


        and control_type = #{param.controlType}


        and control_type = #{param.controlType}


        and create_time >= #{param.beginTime}


        and create_time <= #{param.overTime}



    limit #{param.offset}, #{param.pageSize}
